#include <iostream>
#include <fstream>
#include <cstdlib>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int x[100], y[100];
    for (int i = 0; i < n; i++)
        plik >> x[i] >> y[i];
    int maxD = 0, pi = 0, pj = 1;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int d = abs(x[i] - x[j]) + abs(y[i] - y[j]);
            if (d > maxD) {
                maxD = d;
                pi = i;
                pj = j;
            }
        }
    }
    cout << "Max odleglosc Manhattan: " << maxD << endl;
    cout << "Para: (" << x[pi] << "," << y[pi] << ") i (" << x[pj] << "," << y[pj] << ")" << endl;
    return 0;
}
```

